async function getFeaturedJw(type,country){const all=[],seen=new Set();for(const s of STREAMERS){try{const d=await getJwCatalog(type,s.id,country);for(const m of d.metas.slice(0,20))if(!seen.has(m.id)){seen.add(m.id);all.push(m)}}catch{}}return {metas:all.slice(0,100)}}
