async function getDiscoveryJw(type,mode,country){country=normalizeCountryCode(country);const key=`${mode}:${type}:${country}`,old=discoveryCache.get(key);if(old&&Date.now()-old.t<1800000)return old.v;const q=`query GetPopularTitles($country: Country!,$filter: TitleFilter,$first: Int!,$sortBy: PopularTitlesSorting!){popularTitles(country:$country,filter:$filter,first:$first,sortBy:$sortBy){edges{node{objectType content(country:$country,language:pt){title originalReleaseYear externalIds{imdbId}}}}}}`;const filter={objectTypes:[type==="movie"?"MOVIE":"SHOW"]};if(mode==="cinema")filter.monetizationTypes=["CINEMA"];const d=await jwGraph("GetPopularTitles",q,{country,filter,first:100,sortBy:mode==="popular"?"POPULAR":"TRENDING"}),year=new Date().getUTCFullYear(),seen=new Set(),metas=[];for(const e of d?.popularTitles?.edges||[]){const c=e?.node?.content,id=c?.externalIds?.imdbId;if(!id||seen.has(id))continue;if(mode==="new"&&(!Number(c.originalReleaseYear)||Number(c.originalReleaseYear)<year-1))continue;seen.add(id);metas.push({id,type,name:c.title||"Título",releaseInfo:c.originalReleaseYear?String(c.originalReleaseYear):undefined,poster:`https://images.metahub.space/poster/medium/${id}/img`,background:`https://images.metahub.space/background/medium/${id}/img`})}if(mode==="new")metas.sort((a,b)=>Number(b.releaseInfo||0)-Number(a.releaseInfo||0));let final=metas.slice(0,100);if(mode==="cinema"&&!final.length)final=(await getDiscoveryJw(type,"new",country)).metas.slice(0,100);const v={metas:final};discoveryCache.set(key,{t:Date.now(),v});return v}

